using System.Text;
using System.Text.Json;
using MeshCore.Core;
using MeshCore.Windows;

internal sealed class Fake : IMeshTransport
{
    public event Action<byte[]>? Received;
    public event Action? Disconnected;
    public int MaximumWriteLength { get; set; } = 176;
    public List<byte[]> Sent { get; } = [];
    public Action<byte[]>? Handle;
    public Exception? WriteError;
    public void Emit(byte[] frame) => Received?.Invoke(frame);
    public void Drop() => Disconnected?.Invoke();
    public Task WriteAsync(byte[] frame, CancellationToken cancellation = default) { Sent.Add(frame); Handle?.Invoke(frame); return WriteError == null ? Task.CompletedTask : Task.FromException(WriteError); }
}
internal sealed class AdvancingClock : TimeProvider
{
    private DateTimeOffset utc = DateTimeOffset.FromUnixTimeSeconds(1800000000);
    private long ticks;
    public List<TimeSpan> Waits { get; } = [];
    public override DateTimeOffset GetUtcNow() => utc;
    public override long GetTimestamp() => ticks;
    public override long TimestampFrequency => TimeSpan.TicksPerSecond;
    public void Advance(TimeSpan duration) { utc += duration; ticks += duration.Ticks; }
    public void RewindWallClock() => utc -= TimeSpan.FromHours(1);
    public Task Delay(TimeSpan duration, CancellationToken token) { token.ThrowIfCancellationRequested(); Waits.Add(duration); Advance(duration); return Task.CompletedTask; }
    public RemoteRequestPacer Pacer() => new(this, Delay);
}
internal sealed class MemoryCredentials : ICredentialStore
{
    public readonly Dictionary<string, string> Values = [];
    public string? Load(string key) => Values.GetValueOrDefault(key);
    public void Save(string key, string value) => Values[key] = value;
    public void Delete(string key) => Values.Remove(key);
}
internal static class Program
{
    private static readonly byte[] Key = Enumerable.Range(0, 32).Select(x => (byte)x).ToArray();
    private static readonly string Id = Convert.ToHexStringLower(Key);
    private static int passed, failed;
    private static void Assert(bool condition, string description = "Assertion failed") { if (!condition) throw new Exception(description); }
    private static void Equal<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"Expected {expected}; got {actual}"); }
    private static void Bytes(byte[] expected, byte[] actual) => Equal(Convert.ToHexString(expected), Convert.ToHexString(actual));
    private static void Throws(Action action) { try { action(); } catch (Exception e) when (e is MeshException or ArgumentException or InvalidOperationException) { return; } throw new Exception("Expected rejection"); }
    private static async Task Fails(Func<Task> action) { try { await action(); } catch { return; } throw new Exception("Expected failure"); }
    private static Task Test(string name, Action action) => Test(name, () => { action(); return Task.CompletedTask; });
    private static async Task Test(string name, Func<Task> action) { try { await action(); passed++; System.Console.WriteLine("PASS " + name); } catch (Exception ex) { failed++; System.Console.WriteLine("FAIL " + name + ": " + ex.Message); } }
    private static byte[] Text(string text) => Encoding.UTF8.GetBytes(text);
    private static byte[] Fixed(string text, int count) { byte[] bytes = new byte[count]; Text(text).CopyTo(bytes, 0); return bytes; }
    private static byte[] Sent(uint ack = 1) => [6, 0, .. Codec.U32(ack), .. Codec.U32(2000)];
    private static byte[] Message(string text, byte type = 1, uint timestamp = 42, byte[]? prefix = null) => [7, .. prefix ?? Key[..6], 255, type, .. Codec.U32(timestamp), .. Text(text)];
    private static byte[] Own(string name = "Companion A") => [5, 0, 0, 0, .. Key, .. new byte[12], .. Codec.U32(868000), .. Codec.U32(125000), 7, 5, .. Text(name)];
    private static byte[] Device() => [13, 14, 100, 0, 0x40, 0xe2, 1, 0, .. Fixed("23 Oct 2026", 12), .. Fixed("Heltec T114", 40), .. Fixed("v1.18.0", 20)];
    private static byte[] Contact(byte kind = 2, byte[]? key = null) => [3, .. key ?? Key, kind, 0, 255, .. new byte[64], .. Fixed("Node", 32), .. Codec.U32(123), .. Codec.U32(unchecked((uint)-12500000)), .. Codec.U32(14123456), .. Codec.U32(789)];
    private static byte[] Status() => [0x74, 0x0e, 2, 0, 0x88, 0xff, 0x9c, 0xff, .. Enumerable.Range(1, 8).SelectMany(i => Codec.U32((uint)i * 10)), 1, 0, 0xf6, 0xff, 3, 0, 4, 0, .. Codec.U32(90), .. Codec.U32(100)];
    private static void LocalReplies(Fake t) => t.Handle = frame => { switch (frame[0]) { case 22: t.Emit(Device()); break; case 1: t.Emit(Own()); break; case 20: t.Emit([12, 0x74, 0x0e]); break; case 10: t.Emit([10]); break; default: throw new Exception("Unexpected radio transmission " + frame[0]); } };
    private static async Task<(Fake Transport, Controller Model)> Model()
    { Fake t = new(); LocalReplies(t); Controller model = new(t, new MemoryCredentials(), pacer: new AdvancingClock().Pacer(), remoteTimeout: TimeSpan.FromMilliseconds(40)); await model.Start(); await model.Initialize(123); Assert(model.Initialized, model.Error ?? "Initialization failed"); return (t, model); }
    private static async Task<(Fake Transport, Controller Model, List<string> Commands)> AdminModel(Func<string, string>? responder = null)
    {
        var (t, m) = await Model(); t.Emit(Contact()); await m.SelectNode(Id); List<string> commands = []; uint timestamp = 100;
        t.Handle = frame =>
        {
            if (frame[0] == 10) t.Emit([10]);
            else if (frame[0] == 26) { t.Emit([0x85, 1, .. Key[..6]]); t.Emit(Sent()); }
            else if (frame[0] == 2)
            {
                var command = Encoding.UTF8.GetString(frame[13..]); commands.Add(command);
                var response = responder?.Invoke(command) ?? (command == "ver" ? "v1.18.0-test" : "OK");
                t.Emit(Message(response, 1, timestamp++)); t.Emit(Sent());
            }
            else throw new Exception("Unexpected command " + frame[0]);
        };
        await m.Login("test", false); Assert(m.Admin); return (t, m, commands);
    }
