        await Test("Local store round trip and archive account guard", async () => { LocalStore store = new(); LibraryDocument document = new(); document.Profiles.Add(new() { Account = Id, Name = "Companion" }); await store.Save("library", document, l => l.Validate()); var read = await store.Load("library", () => new LibraryDocument(), l => l.Validate()); Equal(1, read.Profiles.Count); Assert(!ReferenceEquals(read, document)); });
        await Test("Corrupt local file is preserved and never overwritten", async () => { string folder = Path.Combine(Path.GetTempPath(), "MeshCore-test-" + Guid.NewGuid()); Directory.CreateDirectory(folder); try { string path = Path.Combine(folder, "library.json"); await File.WriteAllTextAsync(path, "broken"); LocalStore store = new(folder); await store.Load("library.json", () => new LibraryDocument(), l => l.Validate()); await store.Save("library.json", new LibraryDocument(), l => l.Validate()); Equal("broken", await File.ReadAllTextAsync(path)); Assert(store.Error != null); } finally { Directory.Delete(folder, true); } });
        await Test("Diagnostic export excludes identifying data and raw console", async () => { var (_, m) = await Model(); m.Console.Add(new(DateTimeOffset.UtcNow, Id, "password secret", "password now: secret", "test")); var report = m.DiagnosticReport(); Assert(!report.Contains("secret")); Assert(!report.Contains(Id)); Assert(!report.Contains("Companion A")); Assert(report.Contains(Codec.FirmwareCommit)); });
        await Test("Command evidence distinguishes rejected and unsupported", () => { Equal("Odpověď přijata", CommandEvidence.Classify("> unknown command")); Equal("Výslovně nepodporováno", CommandEvidence.Classify("Unknown command")); Equal("Příkaz vrátil chybu", CommandEvidence.Classify("ERR invalid parameter")); });
        await Test("Configuration save requires explicit confirmation", async () => { var (_, m, commands) = await AdminModel(c => c == "get tx" ? "> 20" : "OK"); await m.ReadConfig(["tx"]); m.Settings.Single(f => f.Key == "tx").Draft = "19"; await m.SaveConfig(["tx"]); Equal(1, commands.Count); Equal("get tx", commands[0]); });
        await Test("Configuration writes are verified by readback", async () => { string tx = "20"; var (_, m, commands) = await AdminModel(c => { if (c.StartsWith("set tx ")) { tx = c[7..]; return "OK"; } return "> " + tx; }); m.Confirm = (_, _) => Task.FromResult(true); await m.ReadConfig(["tx"]); m.Settings.Single(f => f.Key == "tx").Draft = "19"; await m.SaveConfig(["tx"]); Assert(m.Error == null, m.Error ?? ""); Equal("get tx,set tx 19,get tx", string.Join(',', commands)); Equal(0, m.Operations.Pending.Count); Equal("19", m.Settings.Single(f => f.Key == "tx").Actual); });
        await Test("Readback mismatch stops batch and preserves draft", async () => { var (_, m, commands) = await AdminModel(c => c.StartsWith("get ") ? "> 20" : "OK"); m.Confirm = (_, _) => Task.FromResult(true); await m.ReadConfig(["tx", "flood.advert.interval"]); m.Settings.Single(f => f.Key == "tx").Draft = "19"; m.Settings.Single(f => f.Key == "flood.advert.interval").Draft = "25"; await m.SaveConfig(["tx", "flood.advert.interval"]); Assert(m.Error != null); Equal("19", m.Settings.Single(f => f.Key == "tx").Draft); Assert(!commands.Contains("set flood.advert.interval 25")); Equal("19", m.Operations.Pending.Single().Expected); });
        await Test("Alternate duty aliases cannot be written in one batch", async () => { var (_, m, commands) = await AdminModel(c => c == "get af" ? "> 1" : "> 50%"); await m.ReadConfig(["af", "dutycycle"]); m.Settings.Single(f => f.Key == "af").Draft = "9"; m.Settings.Single(f => f.Key == "dutycycle").Draft = "10"; await m.SaveConfig(["af", "dutycycle"]); Assert(m.Error != null); Assert(!commands.Any(c => c.StartsWith("set "))); });
        await Test("Universal setup preserves current values and sends reads only", async () => { var (_, m, commands) = await AdminModel(c => c == "ver" ? "v1.18.0-test" : c == "get dutycycle" ? "> 50%" : c == "get path.hash.mode" ? "> 0" : c == "get owner.info" ? "> Own contact" : "> 60"); await m.PrepareSetup(false, ""); Assert(!m.Settings.Any(f => f.Dirty)); Assert(!commands.Any(c => c.StartsWith("set "))); });
        await Test("Czech setup falls back to af and only stages supported changes", async () => { var (_, m, commands) = await AdminModel(c => c == "get dutycycle" ? "Unknown command" : c == "get af" ? "> 1" : c == "get flood.advert.interval" ? "> 24" : c == "get advert.interval" ? "> 60" : c == "get path.hash.mode" ? "> 0" : c == "ver" ? "v1.18.0-test" : "> Contact"); await m.PrepareSetup(true, ""); Equal("9", m.Settings.Single(f => f.Key == "af").Draft); Equal("25", m.Settings.Single(f => f.Key == "flood.advert.interval").Draft); Equal("0", m.Settings.Single(f => f.Key == "advert.interval").Draft); Assert(!commands.Any(c => c.StartsWith("set "))); });
        await Test("Remote pacing advances whole seconds without future timestamps", async () => { AdvancingClock clock = new(); var pacer = clock.Pacer(); uint first = await pacer.Next(); uint second = await pacer.Next(); uint third = await pacer.Next(); Assert(first < second && second < third); Equal((uint)clock.GetUtcNow().ToUnixTimeSeconds(), third); Assert(clock.Waits.All(w => w >= TimeSpan.FromMilliseconds(1200))); clock.RewindWallClock(); await Fails(async () => { await pacer.Next(); }); });
        await Test("Radio cooldown starts after the reply, not only at request send", async () => { AdvancingClock clock = new(); var pacer = clock.Pacer(); await pacer.Next(); clock.Advance(TimeSpan.FromSeconds(8)); pacer.ReplyReceived(); await pacer.Next(); Equal(TimeSpan.FromMilliseconds(1200), clock.Waits.Single()); });
        await Test("Disconnect during setup clears partial results of the old node", async () => { var (t, m, _) = await AdminModel(c => c == "ver" ? "v1.18.0-test" : "> 24"); var previous = t.Handle; t.Handle = frame => { if (frame[0] == 2 && Encoding.UTF8.GetString(frame[13..]) == "get advert.interval") t.Drop(); else previous!(frame); }; await m.PrepareSetup(true, ""); Assert(!m.Initialized); Equal(0, m.SetupSteps.Count); Assert(m.Settings.All(f => f.State == "Nenačteno" && f.Actual == null)); });
        await Test("CLI timeout includes a repeater airtime and queue allowance", () => { Equal(TimeSpan.FromSeconds(45), RemoteRequestPacer.CliResponseTimeout(2000)); Equal(TimeSpan.FromSeconds(75), RemoteRequestPacer.CliResponseTimeout(60000)); Equal(TimeSpan.FromSeconds(180), RemoteRequestPacer.CliResponseTimeout(uint.MaxValue)); });
        await Test("Firmware replay rule accepts every command in a rapid legacy batch", async () =>
        {
            AdvancingClock clock = new(); Fake t = new(); using MeshSession session = new(t, pacer: clock.Pacer(), remoteTimeout: TimeSpan.FromMilliseconds(40)); uint last = 0; int executed = 0;
            t.Handle = frame => { if (frame[0] == 10) t.Emit([10]); else if (frame[0] == 2) { uint timestamp = System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(frame.AsSpan(3)); if (timestamp > last) { last = timestamp; executed++; t.Emit(Message("> 0", 1, timestamp + 100)); } t.Emit(Sent()); } };
            foreach (var command in new[] { "get flood.advert.interval", "get advert.interval", "get path.hash.mode" }) Equal("> 0", await session.Cli(Key, command)); Equal(3, executed); Assert(!session.RequiresReconnect);
        });
        await Test("Setup failure names the exact read and stops without staging writes", async () =>
        {
            var (t, m, commands) = await AdminModel(c => c == "ver" ? "v1.18.0-test" : "> 24"); var original = t.Handle;
            t.Handle = frame => { if (frame[0] == 2 && Encoding.UTF8.GetString(frame[13..]) == "get advert.interval") { commands.Add("get advert.interval"); t.Emit(Sent()); } else original!(frame); };
            await m.PrepareSetup(true, ""); Assert(m.Error?.Contains("get advert.interval") == true); Assert(m.Session.RequiresReconnect && !m.Admin); Equal(3, commands.Count); Assert(m.SetupSteps.Single(s => s.Command == "get advert.interval").State.StartsWith("Selhalo")); Assert(m.SetupSteps.Single(s => s.Command == "get dutycycle").State == "Neprovedeno"); Assert(!m.Settings.Any(f => f.Dirty)); Equal("24", m.Settings.Single(f => f.Key == "flood.advert.interval").Actual); Equal(null, m.Settings.Single(f => f.Key == "advert.interval").ReadAt); Assert(!commands.Any(c => c.StartsWith("set "))); Assert(m.DiagnosticReport().Contains("get advert.interval"));
        });
