        {
            var (_, m, commands) = await AdminModel(c => c == "get dutycycle" ? "unknown config: dutycycle" : c == "get af" ? "> 1" : c == "get path.hash.mode" ? "> 0" : c == "get owner.info" ? "> " : c == "ver" ? "v1.18.0-test" : "> 24");
            await m.PrepareSetup(true, ""); Equal(null, m.Error); Equal("9", m.Settings.Single(f => f.Key == "af").Draft); Equal("", m.Settings.Single(f => f.Key == "owner.info").Actual); Equal(7, m.SetupSteps.Count); Assert(!commands.Any(c => c.StartsWith("set "))); Assert(Commands.Error("unknown config: dutycycle")); Assert(!Commands.Error("> unknown config: my owner text"));
        });
