        await Test("Disconnect during pacing prevents sending into the next BLE generation", async () => { AdvancingClock clock = new(); Fake t = new(); var pacer = new RemoteRequestPacer(clock, (wait, token) => { clock.Advance(wait); t.Drop(); return Task.CompletedTask; }); using MeshSession session = new(t, pacer: pacer); t.Handle = frame => { if (frame[0] == 10) t.Emit([10]); else { t.Emit(Message("OK", 1, 100)); t.Emit(Sent()); } }; await session.Cli(Key, "ver"); int before = t.Sent.Count; await Fails(() => session.Cli(Key, "board")); Equal(before, t.Sent.Count); });
        await Test("Monitoring remains manual and stops on disconnect", async () => { var (t, m, _) = await AdminModel(); Assert(!m.Monitoring); m.SetMonitoring(true); Assert(m.NextMonitor > DateTimeOffset.UtcNow.AddMinutes(14)); t.Drop(); Assert(!m.Monitoring); });
